// Fixed middleware: the read-modify-write on `hits` is fully synchronous,
// so overlapping invocations cannot interleave between read and write.
const hits = new Map();
async function limiter(req, res, next) {
  const key = req.ip;
  const n = hits.get(key) || 0;
  const count = n + 1; // increment decided synchronously...
  hits.set(key, count); // ...and written back before ANY await
  await recordMetric(key, n); // async gap is now harmless
  if (count > 100) return res.status(429).json({ error: 'rate_limited' });
  next();
}

async function recordMetric(key, n) {
  // Simulated async metric pipeline (network/db/etc).
  await new Promise((resolve) => setImmediate(resolve));
}

module.exports = { hits, limiter, recordMetric };

