const { test } = require('node:test');
const assert = require('node:assert/strict');

function makeReqRes() {
  const req = { ip: '203.0.113.7' };
  return { req };
}

// Fire `total` overlapping requests at the middleware: none is awaited
// until all have been *started*, so they interleave across the middleware's
// internal awaits. Returns { promises, statuses, nextCalls }.
function drive(limiter, total = 200) {
  const promises = [];
  const statuses = [];
  let nextCalls = 0;

  for (let i = 0; i < total; i++) {
    const req = { ip: '203.0.113.7' };
    const res = {
      statusCode: null,
      status(code) {
        this.statusCode = code;
        return this;
      },
      json(body) {
        statuses.push(this.statusCode);
        return this;
      },
    };
    promises.push(
      limiter(req, res, () => {
        nextCalls++;
        statuses.push(200);
      })
    );
  }

  // Let every request run to completion.
  return Promise.all(promises).then(() => ({
    statuses,
    nextCalls,
    limited: statuses.filter((s) => s === 429).length,
  }));
}

test('buggy middleware: read/write separated by await loses increments', async () => {
  const { hits, limiter } = require('./buggy-limiter.js');
  const result = await drive(limiter, 200);

  assert.equal(result.statuses.length, 200, 'all requests completed');
  assert.ok(
    hits.get('203.0.113.7') < 200,
    `counter must end below 200, got ${hits.get('203.0.113.7')}`
  );
});

test('fixed middleware: synchronous increment survives 200 overlapping requests', async () => {
  const { hits, limiter } = require('./limiter.js');
  const result = await drive(limiter, 200);

  assert.equal(hits.get('203.0.113.7'), 200, 'no lost updates');
  assert.equal(result.statuses.length, 200);
  assert.equal(
    result.limited,
    100,
    'requests 101..200 must be rate limited'
  );
  assert.deepEqual(
    result.statuses.slice(0, 100),
    new Array(100).fill(200),
    'requests 1..100 pass through'
  );
  assert.deepEqual(
    result.statuses.slice(100),
    new Array(100).fill(429),
    'request 101 onward get 429'
  );
});

